import React, { useState } from "react";
import axios from "axios";

const PredictionPage = () => {
  const [form, setForm] = useState({
    age: "",
    mmse: "",
    hippocampus: "",
    gender: "",
    memory: "",
    education: ""
  });

  const [modelType, setModelType] = useState("rf");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const values = Object.values(form).map(Number);

    if (values.some(isNaN)) {
      alert("Please fill all fields with numbers.");
      return;
    }

    // Pad remaining features with 0s to make 32 features
    const fullInput = [...values, ...Array(32 - values.length).fill(0)];

    setLoading(true);
    try {
      const res = await axios.post("http://localhost:5000/predict", {
        inputData: fullInput,
        modelType,
      });
      setResult(res.data.prediction === 1 ? "Alzheimer's Detected" : "No Alzheimer's Detected");
    } catch (error) {
      console.error(error);
      setResult("Prediction failed.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ padding: "2rem", fontFamily: "Arial" }}>
      <h2>Alzheimer's Predictor (Key Features Only)</h2>
      <form onSubmit={handleSubmit}>
        <div><label>Age: <input type="number" name="age" value={form.age} onChange={handleChange} required /></label></div>
        <div><label>MMSE Score: <input type="number" name="mmse" value={form.mmse} onChange={handleChange} required /></label></div>
        <div><label>Hippocampus Volume: <input type="number" name="hippocampus" value={form.hippocampus} onChange={handleChange} required /></label></div>
        <div>
          <label>Gender: </label>
          <select name="gender" value={form.gender} onChange={handleChange} required>
            <option value="">Select</option>
            <option value="1">Male</option>
            <option value="0">Female</option>
          </select>
        </div>
        <div><label>Memory Complaint Score: <input type="number" name="memory" value={form.memory} onChange={handleChange} required /></label></div>
        <div><label>Education (years): <input type="number" name="education" value={form.education} onChange={handleChange} required /></label></div>

        <div>
          <label>Select Model: </label>
          <select value={modelType} onChange={(e) => setModelType(e.target.value)}>
            <option value="rf">Random Forest</option>
            <option value="svm">SVM</option>
            <option value="cnn">CNN</option>
          </select>
        </div>

        <button type="submit" disabled={loading}>
          {loading ? "Predicting..." : "Predict"}
        </button>
      </form>

      {result && (
        <div style={{ marginTop: "1rem", fontWeight: "bold" }}>
          Prediction Result: {result}
        </div>
      )}
    </div>
  );
};

export default PredictionPage;
